import sys
from collections import deque

class T:
    __slots__ = ('v', 'l', 'r')
    def __init__(self, v=0, l=None, r=None):
        self.v = v; self.l = l; self.r = r

def build(arr):
    if not arr or arr[0] == 'n':
        return None
    root = T(int(arr[0]))
    q = deque([root])
    i = 1
    while q and i < len(arr):
        n = q.popleft()
        if i < len(arr) and arr[i] != 'n':
            n.l = T(int(arr[i])); q.append(n.l)
        i += 1
        if i < len(arr) and arr[i] != 'n':
            n.r = T(int(arr[i])); q.append(n.r)
        i += 1
    return root

class BSTIteratorBrute:
    def __init__(self, root):
        self.seq = []
        self.idx = 0
        self._inorder(root)
    def _inorder(self, node):
        if not node:
            return
        self._inorder(node.l)
        self.seq.append(node.v)
        self._inorder(node.r)
    def hasNext(self):
        return self.idx < len(self.seq)
    def next(self):
        v = self.seq[self.idx]
        self.idx += 1
        return v

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    root = build(data[1:1 + n])
    q = int(data[1 + n])
    it = BSTIteratorBrute(root)
    ops = data[2 + n:2 + n + q]
    for op in ops:
        if op == 'hasNext':
            print('true' if it.hasNext() else 'false')
        elif op == 'next':
            print(it.next())

